import csv
import re
from decimal import Decimal, InvalidOperation


_AMOUNT_PATTERN = re.compile(r"-?[0-9]+(?:\.[0-9]{1,2})?")
_REQUIRED_HEADERS = {"id", "team", "amount", "status"}
_VALID_STATUSES = {"settled", "pending", "cancelled"}


def read_rows(lines):
    """Parse and validate ledger CSV from a single-pass iterable."""
    rows = []
    seen_ids = set()

    try:
        reader = csv.reader(lines, strict=True)
        header = next(reader, None)
        if header is None or len(header) != 4 or set(header) != _REQUIRED_HEADERS:
            raise ValueError(
                "Header must contain exactly id, team, amount, status"
            )

        for fields in reader:
            if len(fields) != 4:
                raise ValueError(
                    f"CSV row ending at line {reader.line_num} must have exactly four fields"
                )

            row = dict(zip(header, (value.strip() for value in fields)))

            if not row["id"] or not row["team"]:
                raise ValueError("id and team must be nonempty")
            if row["id"] in seen_ids:
                raise ValueError(f"Duplicate id: {row['id']!r}")
            if row["status"] not in _VALID_STATUSES:
                raise ValueError(f"Invalid status: {row['status']!r}")
            if _AMOUNT_PATTERN.fullmatch(row["amount"]) is None:
                raise ValueError(f"Invalid amount: {row['amount']!r}")

            row["amount"] = Decimal(row["amount"])
            seen_ids.add(row["id"])
            rows.append(row)

    except csv.Error as exc:
        raise ValueError(f"Malformed CSV: {exc}") from exc
    except InvalidOperation as exc:
        raise ValueError("Invalid decimal amount") from exc
    except TypeError as exc:
        raise ValueError("Input must be an iterable of CSV text lines") from exc

    return rows

