import csv
import re
from decimal import Decimal, DecimalException

_AMOUNT_PATTERN = re.compile(r"-?[0-9]+(?:\.[0-9]{1,2})?")
_REQUIRED_FIELDS = {"id", "team", "amount", "status"}
_VALID_STATUSES = {"settled", "pending", "cancelled"}


def read_rows(lines):
    try:
        reader = csv.reader(lines, strict=True)
        header = next(reader, None)
        if header is None or len(header) != 4 or set(header) != _REQUIRED_FIELDS:
            raise ValueError("Header must contain exactly id,team,amount,status")

        rows = []
        seen_ids = set()

        for fields in reader:
            if len(fields) != 4:
                raise ValueError("Each row must contain exactly four fields")

            row = dict(zip(header, (value.strip() for value in fields)))

            if not row["id"] or not row["team"]:
                raise ValueError("id and team must be nonempty")
            if row["id"] in seen_ids:
                raise ValueError("Duplicate id")
            if row["status"] not in _VALID_STATUSES:
                raise ValueError("Invalid status")
            if _AMOUNT_PATTERN.fullmatch(row["amount"]) is None:
                raise ValueError("Invalid amount")

            row["amount"] = Decimal(row["amount"])
            seen_ids.add(row["id"])
            rows.append(row)

        return rows
    except (csv.Error, TypeError, UnicodeError, DecimalException) as exc:
        raise ValueError("Invalid CSV input") from exc

